INSERT INTO posts (author_id, title, content, created_at) VALUES
((SELECT id FROM users WHERE email = 'gustavo.exemplo@edu.unifor.br'), 'Como configurar o SSH sem pedir senha toda hora?', 'Quero acessar o servidor da disciplina sem digitar a senha sempre. Chave pública resolve? Qual o passo a passo seguro no Linux?', TIMESTAMPADD(HOUR, -140, NOW())),
((SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Quantos itens cabem em um menu de navegação?', 'No projeto de IHC meu menu tem nove itens e o professor disse que está pesado. Existe um número recomendado ou alguma regra de agrupamento?', TIMESTAMPADD(HOUR, -132, NOW())),
((SELECT id FROM users WHERE email = 'igor.exemplo@edu.unifor.br'), 'Race condition: como reproduzir e corrigir?', 'Meu contador compartilhado entre threads dá valores diferentes a cada execução. Synchronized resolve ou existe algo mais leve para esse caso?', TIMESTAMPADD(HOUR, -122, NOW())),
((SELECT id FROM users WHERE email = 'julia.exemplo@edu.unifor.br'), 'Como lidar com valores ausentes no dataset?', 'Minha base tem 15% de linhas com campos vazios. Descarto essas linhas, preencho com a média ou uso outra técnica? Depende do tipo da coluna?', TIMESTAMPADD(HOUR, -112, NOW())),
((SELECT id FROM users WHERE email = 'kaue.exemplo@edu.unifor.br'), 'Dijkstra funciona com pesos negativos?', 'Estudando grafos vi que Dijkstra falha em alguns casos. O que acontece exatamente com pesos negativos e qual algoritmo usar no lugar?', TIMESTAMPADD(HOUR, -104, NOW())),
((SELECT id FROM users WHERE email = 'larissa.exemplo@edu.unifor.br'), 'Como escrever bons requisitos funcionais?', 'Meus requisitos saem vagos, tipo ''o sistema deve ser rápido''. Existe um formato para deixar cada requisito testável e sem ambiguidade?', TIMESTAMPADD(HOUR, -98, NOW())),
((SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'Normalização: até que forma vale a pena ir?', 'Aprendi até a 3ª forma normal, mas já vi gente desnormalizar de propósito. Em que situação isso compensa em um banco real?', TIMESTAMPADD(HOUR, -90, NOW())),
((SELECT id FROM users WHERE email = 'natalia.exemplo@edu.unifor.br'), 'Posso usar IA para ajudar nos trabalhos?', 'Quero usar assistentes de IA para tirar dúvidas e revisar texto. Onde fica o limite entre ajuda legítima e plágio nas regras da universidade?', TIMESTAMPADD(HOUR, -84, NOW())),
((SELECT id FROM users WHERE email = 'gustavo.exemplo@edu.unifor.br'), 'Diferença entre switch e roteador na prática', 'Na teoria entendo as camadas, mas no laboratório os dois parecem fazer o mesmo. Quando cada um é realmente necessário em uma rede?', TIMESTAMPADD(HOUR, -78, NOW())),
((SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Responsivo: mobile-first ou desktop-first?', 'Vou começar o front do projeto e fiquei na dúvida sobre por onde começar o CSS. Mobile-first realmente facilita ou é só modinha?', TIMESTAMPADD(HOUR, -72, NOW())),
((SELECT id FROM users WHERE email = 'igor.exemplo@edu.unifor.br'), 'O que é consistência eventual?', 'Li que alguns bancos distribuídos aceitam consistência eventual. Isso significa que posso ler dado desatualizado? Em que apps isso é aceitável?', TIMESTAMPADD(HOUR, -66, NOW())),
((SELECT id FROM users WHERE email = 'julia.exemplo@edu.unifor.br'), 'Como escolher o número de clusters no k-means?', 'Rodei o k-means com k=3 por intuição. Existe um método (cotovelo, silhouette) para justificar a escolha do k de forma mais confiável?', TIMESTAMPADD(HOUR, -58, NOW())),
((SELECT id FROM users WHERE email = 'kaue.exemplo@edu.unifor.br'), 'Para que serve matriz de rotação em jogos?', 'No curso de álgebra vimos matrizes de rotação, mas não entendi onde isso aparece em jogos 2D. É só para girar sprites?', TIMESTAMPADD(HOUR, -52, NOW())),
((SELECT id FROM users WHERE email = 'larissa.exemplo@edu.unifor.br'), 'Scrum ou Kanban para equipe de quatro pessoas?', 'Nosso grupo tem quatro pessoas e entregas quinzenais. Scrum completo parece exagero. Kanban simples dá conta ou perdemos algo importante?', TIMESTAMPADD(HOUR, -46, NOW())),
((SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'Interface ou classe abstrata?', 'Sempre confundo quando criar uma interface e quando uma classe abstrata. Tem um critério simples que funcione na maioria dos casos?', TIMESTAMPADD(HOUR, -40, NOW())),
((SELECT id FROM users WHERE email = 'natalia.exemplo@edu.unifor.br'), 'Como escolher um tema de pesquisa para o TCC?', 'Quero um tema que seja viável em um semestre. Como saber se o escopo está grande demais e como começar a revisão bibliográfica?', TIMESTAMPADD(HOUR, -34, NOW())),
((SELECT id FROM users WHERE email = 'ana.exemplo@edu.unifor.br'), 'Árvore binária de busca ou tabela hash?', 'Para um dicionário de palavras, qual estrutura é melhor? Entendo a complexidade média, mas e a necessidade de manter os dados ordenados?', TIMESTAMPADD(HOUR, -28, NOW())),
((SELECT id FROM users WHERE email = 'bruno.exemplo@edu.unifor.br'), 'Como guardar dados localmente no app mobile?', 'Meu app precisa funcionar sem internet. Qual a melhor forma de guardar dados no aparelho: arquivo, banco local ou preferências?', TIMESTAMPADD(HOUR, -18, NOW())),
((SELECT id FROM users WHERE email = 'diego.exemplo@edu.unifor.br'), 'Monolito ou microsserviços para começar?', 'Nosso projeto é pequeno, mas me falaram para já usar microsserviços. Isso faz sentido no início ou complica sem necessidade?', TIMESTAMPADD(HOUR, -10, NOW())),
((SELECT id FROM users WHERE email = 'elisa.exemplo@edu.unifor.br'), 'Como estimar a complexidade de um algoritmo?', 'Sei que O(n) é linear e O(n²) é quadrático, mas na hora de analisar um código com laços aninhados eu me perco. Qual o passo a passo?', TIMESTAMPADD(HOUR, -3, NOW()));
