INSERT INTO post_comments (post_id, author_id, content, created_at) VALUES
((SELECT MAX(id) FROM posts WHERE title = 'Como configurar o SSH sem pedir senha toda hora?'), (SELECT id FROM users WHERE email = 'elisa.exemplo@edu.unifor.br'), 'Gere um par de chaves com ssh-keygen, copie a pública com ssh-copy-id e proteja a privada com uma passphrase. Assim não precisa digitar a senha do servidor.', TIMESTAMPADD(HOUR, -136, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como configurar o SSH sem pedir senha toda hora?'), (SELECT id FROM users WHERE email = 'diego.exemplo@edu.unifor.br'), 'Depois desative o login por senha no sshd_config para ficar mais seguro.', TIMESTAMPADD(HOUR, -130, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Quantos itens cabem em um menu de navegação?'), (SELECT id FROM users WHERE email = 'ana.exemplo@edu.unifor.br'), 'Agrupar em 5 a 7 itens ajuda bastante. O resto pode ir em submenus ou em uma área "Mais".', TIMESTAMPADD(HOUR, -126, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Quantos itens cabem em um menu de navegação?'), (SELECT id FROM users WHERE email = 'bruno.exemplo@edu.unifor.br'), 'Teste de ordenação de cartões com colegas mostra bem como as pessoas agrupariam.', TIMESTAMPADD(HOUR, -124, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Race condition: como reproduzir e corrigir?'), (SELECT id FROM users WHERE email = 'felipe.exemplo@edu.unifor.br'), 'Synchronized resolve, mas para contador simples o AtomicInteger é mais leve e já é thread-safe.', TIMESTAMPADD(HOUR, -118, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como lidar com valores ausentes no dataset?'), (SELECT id FROM users WHERE email = 'carla.exemplo@edu.unifor.br'), 'Depende: para numéricas a mediana costuma ser mais segura que a média. Para categorias, uma classe "desconhecido" ou a moda.', TIMESTAMPADD(HOUR, -108, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como lidar com valores ausentes no dataset?'), (SELECT id FROM users WHERE email = 'elisa.exemplo@edu.unifor.br'), 'Antes de preencher, confira se os dados ausentes seguem algum padrão.', TIMESTAMPADD(HOUR, -106, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Dijkstra funciona com pesos negativos?'), (SELECT id FROM users WHERE email = 'igor.exemplo@edu.unifor.br'), 'Com pesos negativos Dijkstra pode fechar um nó cedo demais. Use Bellman-Ford, que aceita pesos negativos.', TIMESTAMPADD(HOUR, -100, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como escrever bons requisitos funcionais?'), (SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'Eu uso o modelo ''O sistema deve <verbo> <objeto> em <condição mensurável>''. Exemplo: responder em até 2 s.', TIMESTAMPADD(HOUR, -94, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como escrever bons requisitos funcionais?'), (SELECT id FROM users WHERE email = 'ana.exemplo@edu.unifor.br'), 'Pense em como você testaria cada requisito. Se não dá para testar, está vago.', TIMESTAMPADD(HOUR, -92, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Normalização: até que forma vale a pena ir?'), (SELECT id FROM users WHERE email = 'diego.exemplo@edu.unifor.br'), 'Desnormaliza quando a leitura é muito mais frequente que a escrita e os joins estão caros, e mede antes.', TIMESTAMPADD(HOUR, -86, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Normalização: até que forma vale a pena ir?'), (SELECT id FROM users WHERE email = 'julia.exemplo@edu.unifor.br'), 'Em relatórios e data warehouses é comum desnormalizar de propósito.', TIMESTAMPADD(HOUR, -85, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Posso usar IA para ajudar nos trabalhos?'), (SELECT id FROM users WHERE email = 'carla.exemplo@edu.unifor.br'), 'Confira o regulamento da disciplina e sempre declare o uso. Usar para entender é diferente de entregar texto gerado como seu.', TIMESTAMPADD(HOUR, -80, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Posso usar IA para ajudar nos trabalhos?'), (SELECT id FROM users WHERE email = 'felipe.exemplo@edu.unifor.br'), 'Eu uso só para explicações e depois refaço com minhas palavras.', TIMESTAMPADD(HOUR, -78, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Diferença entre switch e roteador na prática'), (SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Switch liga dispositivos da mesma rede; roteador conecta redes diferentes e decide o caminho dos pacotes.', TIMESTAMPADD(HOUR, -74, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Responsivo: mobile-first ou desktop-first?'), (SELECT id FROM users WHERE email = 'bruno.exemplo@edu.unifor.br'), 'Mobile-first ajuda a priorizar o essencial e o CSS fica menor. Depois você só acrescenta com media queries.', TIMESTAMPADD(HOUR, -70, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Responsivo: mobile-first ou desktop-first?'), (SELECT id FROM users WHERE email = 'gustavo.exemplo@edu.unifor.br'), 'Concordo, e evita ter que desfazer estilos no mobile.', TIMESTAMPADD(HOUR, -68, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'O que é consistência eventual?'), (SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'Sim, pode ler dado antigo por um tempo. Serve para curtidas e contadores, mas não para saldo bancário.', TIMESTAMPADD(HOUR, -62, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como escolher o número de clusters no k-means?'), (SELECT id FROM users WHERE email = 'felipe.exemplo@edu.unifor.br'), 'Método do cotovelo: plote a soma dos erros por k e escolha onde a curva para de cair rápido. A silhouette confirma.', TIMESTAMPADD(HOUR, -54, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Para que serve matriz de rotação em jogos?'), (SELECT id FROM users WHERE email = 'igor.exemplo@edu.unifor.br'), 'Aparece também em câmera, projéteis e animações de personagens, não só sprites.', TIMESTAMPADD(HOUR, -48, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Scrum ou Kanban para equipe de quatro pessoas?'), (SELECT id FROM users WHERE email = 'ana.exemplo@edu.unifor.br'), 'Para quatro pessoas Kanban com limite de tarefas em andamento funciona bem. Faça uma retro rápida a cada entrega.', TIMESTAMPADD(HOUR, -42, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Scrum ou Kanban para equipe de quatro pessoas?'), (SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'Concordo. Scrum só se vocês precisarem mesmo das cerimônias.', TIMESTAMPADD(HOUR, -41, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Interface ou classe abstrata?'), (SELECT id FROM users WHERE email = 'diego.exemplo@edu.unifor.br'), 'Interface define o contrato; classe abstrata compartilha código. Se precisa herdar implementação, abstrata.', TIMESTAMPADD(HOUR, -36, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como escolher um tema de pesquisa para o TCC?'), (SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Comece lendo artigos recentes da área que mais gostou e veja o que ficou em aberto. Isso vira tema.', TIMESTAMPADD(HOUR, -30, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como escolher um tema de pesquisa para o TCC?'), (SELECT id FROM users WHERE email = 'larissa.exemplo@edu.unifor.br'), 'Converse com um professor orientador cedo, ele ajuda a recortar o escopo.', TIMESTAMPADD(HOUR, -28, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Árvore binária de busca ou tabela hash?'), (SELECT id FROM users WHERE email = 'igor.exemplo@edu.unifor.br'), 'Para dicionário a tabela hash é mais rápida em média. Se precisa de ordem, a árvore balanceada.', TIMESTAMPADD(HOUR, -24, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Árvore binária de busca ou tabela hash?'), (SELECT id FROM users WHERE email = 'kaue.exemplo@edu.unifor.br'), 'E dá para combinar: hash para busca e árvore para listar em ordem.', TIMESTAMPADD(HOUR, -22, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como guardar dados localmente no app mobile?'), (SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Para dados estruturados, um banco local como SQLite. Preferências só para configurações simples.', TIMESTAMPADD(HOUR, -14, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Monolito ou microsserviços para começar?'), (SELECT id FROM users WHERE email = 'gustavo.exemplo@edu.unifor.br'), 'Para projeto pequeno, comece com monolito bem organizado. Dá para separar depois se precisar.', TIMESTAMPADD(HOUR, -8, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Monolito ou microsserviços para começar?'), (SELECT id FROM users WHERE email = 'larissa.exemplo@edu.unifor.br'), 'Microsserviços trazem custo de infraestrutura e comunicação; só valem quando o time e a carga pedem.', TIMESTAMPADD(HOUR, -6, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como estimar a complexidade de um algoritmo?'), (SELECT id FROM users WHERE email = 'kaue.exemplo@edu.unifor.br'), 'Cada laço aninhado costuma multiplicar o custo. Dois laços de 0 a n dão n².', TIMESTAMPADD(HOUR, -2, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Diferença entre pilha e fila na prática?'), (SELECT id FROM users WHERE email = 'gustavo.exemplo@edu.unifor.br'), 'Fila também aparece em impressão e em filas de requisições de um servidor. Pilha, na chamada de funções.', TIMESTAMPADD(HOUR, -60, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Como saber se preciso de um índice na tabela?'), (SELECT id FROM users WHERE email = 'julia.exemplo@edu.unifor.br'), 'Rode EXPLAIN na consulta: se aparecer varredura completa da tabela, um índice na coluna do WHERE ajuda muito.', TIMESTAMPADD(HOUR, -40, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'CORS bloqueando minha API local'), (SELECT id FROM users WHERE email = 'mateus.exemplo@edu.unifor.br'), 'No Spring, configure o CorsConfigurationSource liberando a origem do front e o cabeçalho Authorization.', TIMESTAMPADD(HOUR, -34, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Overfitting: como perceber que aconteceu?'), (SELECT id FROM users WHERE email = 'julia.exemplo@edu.unifor.br'), 'Separe um conjunto de validação e acompanhe o erro nele a cada época: se o de treino cai e o de validação sobe, é overfitting.', TIMESTAMPADD(HOUR, -22, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'Kotlin ou Flutter para o projeto da disciplina?'), (SELECT id FROM users WHERE email = 'helena.exemplo@edu.unifor.br'), 'Flutter tem hot reload e uma base de código só, o que ajuda quando o prazo é curto.', TIMESTAMPADD(HOUR, -14, NOW())),
((SELECT MAX(id) FROM posts WHERE title = 'BFS ou DFS para achar menor caminho?'), (SELECT id FROM users WHERE email = 'kaue.exemplo@edu.unifor.br'), 'Dica de memória: BFS usa fila e acha o caminho mais curto sem pesos; DFS usa pilha e explora fundo.', TIMESTAMPADD(HOUR, -2, NOW()));
